import{_ as e,o as i,c as o,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"El Sistema de Educación Simbiótica","description":"","frontmatter":{},"headers":[],"relativePath":"es/0037-共生教育体系.md","filePath":"es/0037-共生教育体系.md"}'),s={name:"es/0037-共生教育体系.md"};function t(d,a,r,c,l,u){return i(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="el-sistema-de-educacion-simbiotica" tabindex="-1">El Sistema de Educación Simbiótica <a class="header-anchor" href="#el-sistema-de-educacion-simbiotica" aria-label="Permalink to &quot;El Sistema de Educación Simbiótica&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>37</td></tr><tr><td>Módulo</td><td>Tipos de Civilización y Sistemas Sociales</td></tr><tr><td>Palabras clave</td><td>Educación Simbiótica, Aprendizaje Permanente, Sistemas Abiertos, Enseñanza según Aptitudes, Equidad Educativa</td></tr></tbody></table><h2 id="i-conceptos-fundamentales-y-objetivos-de-la-educacion-simbiotica" tabindex="-1">I. Conceptos Fundamentales y Objetivos de la Educación Simbiótica <a class="header-anchor" href="#i-conceptos-fundamentales-y-objetivos-de-la-educacion-simbiotica" aria-label="Permalink to &quot;I. Conceptos Fundamentales y Objetivos de la Educación Simbiótica&quot;">​</a></h2><p>La educación es la piedra angular de la herencia y el desarrollo de la civilización. En la era del Sistema de Cultivo Depredador, la educación estaba monopolizada por unos pocos poderosos y sectas, y las masas de la base casi no tenían oportunidad de recibir educación formal. Este monopolio educativo no solo causó la solidificación de clases, sino que también condujo a la baja eficiencia de la evolución general de la civilización: el potencial de la gran mayoría de las vidas se desperdiciaba, mientras que unos pocos monopolistas, para proteger sus privilegios, restringían deliberadamente la difusión del conocimiento y la innovación.</p><p>Tras el establecimiento de la Civilización Simbiótica del Ancla, la construcción de un sistema de educación simbiótica abierto, justo y de calidad se convirtió en una de sus tareas centrales. El concepto fundamental de la educación simbiótica puede resumirse en dieciséis caracteres: &quot;Un Camino para Todos, Enseñanza según Aptitudes, Aprendizaje Permanente, Avance Conjunto de las Diez Mil Razas&quot;.</p><p>Los objetivos fundamentales de la educación simbiótica incluyen:</p><ol><li><strong>Universalizar la educación básica de cultivo</strong>: garantizar que cada vida simbiótica pueda adquirir conocimientos y capacidades básicas de cultivo, realizando &quot;Un Camino para Todos&quot;</li><li><strong>Formar talentos de cultivo de alto nivel</strong>: a través de la educación avanzada y la educación de élite, formar talentos de alto nivel en todos los campos, proporcionando soporte intelectual al desarrollo de la civilización</li><li><strong>Promover el desarrollo integral del individuo</strong>: no solo cultivar la capacidad de cultivo, sino también prestar atención al desarrollo de cualidades integrales como la moralidad, la sabiduría, la creatividad y la responsabilidad social</li><li><strong>Promover la herencia y la innovación de la civilización</strong>: realizar la herencia intergeneracional de la civilización a través de la educación, al tiempo que se estimula la vitalidad innovadora y se impulsa el progreso continuo de la civilización</li><li><strong>Servir al avance de las Diez Mil Razas</strong>: el sistema educativo está abierto a todas las razas y formas de vida, promoviendo el intercambio y el progreso común entre las Diez Mil Razas</li></ol><h2 id="ii-el-sistema-de-cuatro-niveles-de-la-educacion-simbiotica" tabindex="-1">II. El Sistema de Cuatro Niveles de la Educación Simbiótica <a class="header-anchor" href="#ii-el-sistema-de-cuatro-niveles-de-la-educacion-simbiotica" aria-label="Permalink to &quot;II. El Sistema de Cuatro Niveles de la Educación Simbiótica&quot;">​</a></h2><p>Según la etapa educativa y los objetivos de formación, el sistema de educación simbiótica se divide en cuatro niveles, formando una cadena educativa completa:</p><table tabindex="0"><thead><tr><th>Nivel</th><th>Nombre</th><th>Destinatarios</th><th>Objetivos Fundamentales</th><th>Duración</th><th>Costo</th></tr></thead><tbody><tr><td>Primer nivel</td><td>Educación de Iniciación</td><td>Todas las vidas menores</td><td>Conocimientos básicos, iniciación al cultivo, despertar moral</td><td>6-9 años</td><td>Gratuita</td></tr><tr><td>Segundo nivel</td><td>Educación Básica</td><td>Quienes completaron la iniciación</td><td>Conocimientos sistemáticos de cultivo, capacidad básica de cultivo, cualidades integrales</td><td>3-6 años</td><td>Gratuita</td></tr><tr><td>Tercer nivel</td><td>Educación Avanzada</td><td>Quienes superaron la evaluación básica</td><td>Habilidades profesionales de cultivo, investigación profunda de sistemas, capacidad de innovación</td><td>3-9 años</td><td>Cuota baja/becas</td></tr><tr><td>Cuarto nivel</td><td>Educación de Élite</td><td>Individuos de alto potencial seleccionados</td><td>Reinos de cultivo de élite, investigación de leyes, capacidad de liderazgo civilizacional</td><td>Sin límite</td><td>Financiación total</td></tr></tbody></table><h3 id="_2-1-educacion-de-iniciacion" tabindex="-1">2.1 Educación de Iniciación <a class="header-anchor" href="#_2-1-educacion-de-iniciacion" aria-label="Permalink to &quot;2.1 Educación de Iniciación&quot;">​</a></h3><p>La educación de iniciación es el punto de partida del sistema de educación simbiótica. Abierta a todas las vidas menores, es completamente gratuita. Sus contenidos fundamentales incluyen:</p><ul><li><strong>Conocimientos básicos</strong>: lengua y escritura, lógica matemática, conocimientos generales del cosmos, historia de la civilización, etc.</li><li><strong>Iniciación al cultivo</strong>: introducción básica a los Trescientos Sistemas de Cultivo del Origen, técnicas respiratorias fundamentales, entrenamiento de percepción de energía, etc.</li><li><strong>Despertar moral</strong>: cultivo de los conceptos simbióticos, la ética moral, la responsabilidad social y el valor de la igualdad de las Diez Mil Razas</li><li><strong>Descubrimiento de intereses</strong>: a través de cursos y actividades diversificados, ayudar a cada niño a descubrir sus propios intereses y talentos</li></ul><p>La educación de iniciación enfatiza el &quot;aprendizaje feliz, desarrollo integral&quot;. No realiza competencias feroces ni selecciones, sino que se centra en proteger la curiosidad y la creatividad de los niños.</p><h3 id="_2-2-educacion-basica" tabindex="-1">2.2 Educación Básica <a class="header-anchor" href="#_2-2-educacion-basica" aria-label="Permalink to &quot;2.2 Educación Básica&quot;">​</a></h3><p>La educación básica está orientada a los adolescentes que completaron la educación de iniciación y también es completamente gratuita. Sus contenidos fundamentales incluyen:</p><ul><li><strong>Conocimientos sistemáticos de cultivo</strong>: estudio y comprensión sistemáticos de los Trescientos Sistemas de Cultivo del Origen</li><li><strong>Capacidad básica de cultivo</strong>: dominar al menos un sistema de cultivo básico, alcanzando el nivel de cultivador inicial</li><li><strong>Formación de cualidades integrales</strong>: desarrollo integral de la alfabetización científica, humanística, artística y de la aptitud física</li><li><strong>Práctica social</strong>: a través del servicio comunitario, actividades prácticas, etc., desarrollar la responsabilidad social y la capacidad práctica</li></ul><p>Al final de la etapa de educación básica, los estudiantes deben realizar una evaluación básica. Quienes la superen pueden entrar en la educación avanzada; quienes no, pueden elegir repetirla o incorporarse directamente a la sociedad para realizar trabajos básicos.</p><h3 id="_2-3-educacion-avanzada" tabindex="-1">2.3 Educación Avanzada <a class="header-anchor" href="#_2-3-educacion-avanzada" aria-label="Permalink to &quot;2.3 Educación Avanzada&quot;">​</a></h3><p>La educación avanzada está orientada a los cultivadores que superaron la evaluación básica y funciona mediante una combinación de cuota baja y becas. Sus contenidos fundamentales incluyen:</p><ul><li><strong>Direcciones profesionales de cultivo</strong>: los estudiantes eligen sus sistemas de cultivo principales y direcciones profesionales para un estudio profundo</li><li><strong>Entrenamiento práctico de cultivo</strong>: bajo la guía de mentores, realizar abundantes prácticas de cultivo para mejorar las capacidades reales</li><li><strong>Capacidad de I+D tecnológica</strong>: desarrollar la capacidad de investigación y desarrollo en tecnología de cultivo y tecnología de ingeniería</li><li><strong>Formación de cualidades profesionales</strong>: desarrollar la ética profesional, el trabajo en equipo, la comunicación y expresión, etc.</li></ul><p>La educación avanzada se divide en múltiples direcciones profesionales, que cubren el cultivo, la tecnología, la gestión, la educación, la medicina, las artes y otros campos. Los estudiantes pueden elegir su dirección profesional según sus intereses y talentos.</p><h3 id="_2-4-educacion-de-elite" tabindex="-1">2.4 Educación de Élite <a class="header-anchor" href="#_2-4-educacion-de-elite" aria-label="Permalink to &quot;2.4 Educación de Élite&quot;">​</a></h3><p>La educación de élite está orientada a cultivadores de alto potencial seleccionados mediante un estricto examen, financiada íntegramente por la civilización simbiótica. Sus contenidos fundamentales incluyen:</p><ul><li><strong>Orientación de cultivo de élite</strong>: tutoría individualizada por mentores de nivel Potencia Suprema del Plano</li><li><strong>Investigación profunda de leyes</strong>: estudio profundo de las Leyes del Origen del universo, explorando los misterios últimos del cultivo</li><li><strong>Capacidad de liderazgo civilizacional</strong>: desarrollar el pensamiento estratégico, la capacidad de gobernanza, la capacidad de innovación y otras cualidades indispensables para los líderes de la civilización</li><li><strong>Visión transplanar</strong>: a través del intercambio y la exploración transplanar, desarrollar una visión y un horizonte a escala universal</li></ul><p>El objetivo de la educación de élite es formar a los futuros líderes de la civilización simbiótica, por lo que la selección es extremadamente estricta y los recursos de formación extremadamente abundantes.</p><h2 id="iii-principios-fundamentales-de-la-educacion-simbiotica" tabindex="-1">III. Principios Fundamentales de la Educación Simbiótica <a class="header-anchor" href="#iii-principios-fundamentales-de-la-educacion-simbiotica" aria-label="Permalink to &quot;III. Principios Fundamentales de la Educación Simbiótica&quot;">​</a></h2><h3 id="_3-1-el-principio-de-equidad-educativa" tabindex="-1">3.1 El Principio de Equidad Educativa <a class="header-anchor" href="#_3-1-el-principio-de-equidad-educativa" aria-label="Permalink to &quot;3.1 El Principio de Equidad Educativa&quot;">​</a></h3><p>La equidad educativa es el primer principio de la educación simbiótica. La civilización simbiótica garantiza la equidad educativa mediante las siguientes medidas:</p><ul><li><strong>Educación básica gratuita</strong>: la educación de iniciación y la educación básica son completamente gratuitas, garantizando que cada niño pueda asistir a la escuela</li><li><strong>Equilibrio de recursos educativos</strong>: a través de la Red del Ancla, realizar el intercambio remoto de recursos educativos de calidad, reduciendo las brechas regionales</li><li><strong>Compensación a grupos desfavorecidos</strong>: proporcionar apoyo educativo adicional a las familias pobres, razas especiales, vidas discapacitadas y otros grupos desfavorecidos</li><li><strong>Criterios de selección unificados</strong>: la selección para la educación avanzada y de élite utiliza la capacidad y el potencial como únicos criterios, sin considerar el origen ni la riqueza</li></ul><h3 id="_3-2-el-principio-de-ensenanza-segun-aptitudes" tabindex="-1">3.2 El Principio de Enseñanza según Aptitudes <a class="header-anchor" href="#_3-2-el-principio-de-ensenanza-segun-aptitudes" aria-label="Permalink to &quot;3.2 El Principio de Enseñanza según Aptitudes&quot;">​</a></h3><p>La educación simbiótica enfatiza la enseñanza según las aptitudes, respetando las diferencias de cada individuo:</p><ul><li><strong>Evaluación personalizada</strong>: cada estudiante recibe una evaluación integral de su personalidad al ingresar, incluyendo talentos, intereses, rasgos, estilos de aprendizaje, etc.</li><li><strong>Planes de aprendizaje personalizados</strong>: según los resultados de la evaluación, formular un plan de aprendizaje personalizado para cada estudiante</li><li><strong>Oferta diversificada de cursos</strong>: proporcionar una rica variedad de cursos para elegir, satisfaciendo diferentes intereses y direcciones de desarrollo</li><li><strong>Ritmo de aprendizaje flexible</strong>: permitir a los estudiantes ajustar su ritmo de aprendizaje; los rápidos pueden saltar de nivel, los lentos pueden extender el tiempo</li></ul><h3 id="_3-3-el-principio-de-aprendizaje-permanente" tabindex="-1">3.3 El Principio de Aprendizaje Permanente <a class="header-anchor" href="#_3-3-el-principio-de-aprendizaje-permanente" aria-label="Permalink to &quot;3.3 El Principio de Aprendizaje Permanente&quot;">​</a></h3><p>La educación simbiótica no se limita a la etapa menor, sino que atraviesa toda la vida de cada individuo:</p><ul><li><strong>Educación continua de adultos</strong>: proporcionar a los adultos oportunidades de aprendizaje continuo y mejora de habilidades</li><li><strong>Formación de reconversión</strong>: proporcionar apoyo formativo a quienes necesitan cambiar de dirección de cultivo o de profesión</li><li><strong>Aprendizaje de mayores</strong>: proporcionar a los cultivadores mayores oportunidades de aprendizaje en salud, cultura, intereses, etc.</li><li><strong>Plataformas de aprendizaje en línea</strong>: proporcionar abundantes recursos de aprendizaje en línea a través de la red simbiótica, permitiendo aprender en cualquier momento y lugar</li></ul><h3 id="_3-4-el-principio-de-orientacion-practica" tabindex="-1">3.4 El Principio de Orientación Práctica <a class="header-anchor" href="#_3-4-el-principio-de-orientacion-practica" aria-label="Permalink to &quot;3.4 El Principio de Orientación Práctica&quot;">​</a></h3><p>La educación simbiótica enfatiza la combinación de teoría y práctica:</p><ul><li><strong>Práctica de cultivo</strong>: los estudiantes realizan abundantes prácticas de cultivo mientras aprenden teoría</li><li><strong>Pasantías y prácticas</strong>: la etapa de educación avanzada organiza abundantes pasantías, permitiendo a los estudiantes entrenarse en entornos reales</li><li><strong>Aprendizaje por proyectos</strong>: impulsado por proyectos reales, desarrollando la capacidad de los estudiantes para resolver problemas reales</li><li><strong>Cooperación escuela-empresa</strong>: las instituciones educativas cooperan estrechamente con las instituciones de cultivo y las empresas para formar talentos conjuntamente</li></ul><h2 id="iv-garantias-de-profesorado-y-recursos-para-la-educacion-simbiotica" tabindex="-1">IV. Garantías de Profesorado y Recursos para la Educación Simbiótica <a class="header-anchor" href="#iv-garantias-de-profesorado-y-recursos-para-la-educacion-simbiotica" aria-label="Permalink to &quot;IV. Garantías de Profesorado y Recursos para la Educación Simbiótica&quot;">​</a></h2><h3 id="_4-1-desarrollo-del-profesorado" tabindex="-1">4.1 Desarrollo del Profesorado <a class="header-anchor" href="#_4-1-desarrollo-del-profesorado" aria-label="Permalink to &quot;4.1 Desarrollo del Profesorado&quot;">​</a></h3><p>La civilización simbiótica ha establecido un sistema completo de formación y gestión del profesorado:</p><ul><li><strong>Certificación docente</strong>: todos los profesores deben superar una estricta certificación, garantizando la calidad de la enseñanza</li><li><strong>Formación continua del profesorado</strong>: los profesores deben participar periódicamente en formaciones para actualizar conocimientos y mejorar capacidades docentes</li><li><strong>Mecanismo de incentivo a mentores</strong>: los excelentes mentores pueden recibir honores, cuotas de recursos, oportunidades de promoción, etc.</li><li><strong>Sistema de obligación de mentores</strong>: los cultivadores avanzados tienen la obligación de actuar como mentores y guiar a los cultivadores iniciales</li></ul><h3 id="_4-2-garantias-de-recursos-educativos" tabindex="-1">4.2 Garantías de Recursos Educativos <a class="header-anchor" href="#_4-2-garantias-de-recursos-educativos" aria-label="Permalink to &quot;4.2 Garantías de Recursos Educativos&quot;">​</a></h3><p>La civilización simbiótica garantiza un suministro adecuado de recursos educativos por diversos medios:</p><ul><li><strong>Inversión financiera pública</strong>: las finanzas gubernamentales priorizan la inversión educativa; el gasto educativo no debe ser inferior a la proporción legalmente establecida del gasto público</li><li><strong>Fuerzas sociales en la educación</strong>: alentar a sectas, empresas, organizaciones sin fines de lucro y otras fuerzas sociales a participar en la gestión de escuelas</li><li><strong>Mecanismo de intercambio de recursos</strong>: a través de la Red del Ancla, realizar el intercambio global de recursos educativos de calidad</li><li><strong>Apertura de recursos educativos</strong>: las técnicas fundamentales de los Trescientos Sistemas de Cultivo del Origen están totalmente abiertas de forma gratuita como recursos educativos</li></ul><h3 id="_4-3-aplicacion-de-tecnologias-educativas" tabindex="-1">4.3 Aplicación de Tecnologías Educativas <a class="header-anchor" href="#_4-3-aplicacion-de-tecnologias-educativas" aria-label="Permalink to &quot;4.3 Aplicación de Tecnologías Educativas&quot;">​</a></h3><p>La civilización simbiótica aprovecha plenamente las tecnologías avanzadas para mejorar la calidad educativa:</p><ul><li><strong>Enseñanza a distancia</strong>: a través de la Red del Ancla, realizar enseñanza a distancia interregional y transplanar</li><li><strong>Tutoría inteligente</strong>: utilizar tecnologías de inteligencia artificial para proporcionar tutoría inteligente personalizada a los estudiantes</li><li><strong>Cultivo simulado</strong>: utilizar tecnologías de espacio virtual para proporcionar un entorno seguro de cultivo simulado</li><li><strong>Análisis de datos</strong>: utilizar el análisis de macrodatos sobre las situaciones de aprendizaje de los estudiantes para proporcionar recomendaciones docentes precisas</li></ul><h2 id="v-diferencias-en-los-modelos-educativos-de-los-cinco-tipos-de-civilizacion" tabindex="-1">V. Diferencias en los Modelos Educativos de los Cinco Tipos de Civilización <a class="header-anchor" href="#v-diferencias-en-los-modelos-educativos-de-los-cinco-tipos-de-civilizacion" aria-label="Permalink to &quot;V. Diferencias en los Modelos Educativos de los Cinco Tipos de Civilización&quot;">​</a></h2><p>Los cinco tipos de civilización simbiótica tienen sus propias características en los modelos educativos:</p><table tabindex="0"><thead><tr><th>Tipo</th><th>Características del Modelo Educativo</th><th>Ventajas</th></tr></thead><tbody><tr><td>Tipo Intensivo de Asia Oriental</td><td>A gran escala, estandarizado, evaluación estricta</td><td>Alta eficiencia de formación, base sólida</td></tr><tr><td>Tipo Nórdico de Bienestar</td><td>Universal, personalizado, baja presión</td><td>Fuerte sensación de bienestar, buena creatividad</td></tr><tr><td>Tipo Pluralista Norteamericano</td><td>Elección independiente, selección competitiva, educación de élite</td><td>Fuerte innovación, muchos talentos de élite</td></tr><tr><td>Tipo Social Europeo Continental</td><td>Sistema dual, cooperación escuela-empresa, orientación profesional</td><td>Fuerte capacidad práctica, alta adecuación al empleo</td></tr><tr><td>Tipo de Desarrollo y Alcance</td><td>Liderado por élites, rápida popularización, aprendizaje y préstamo</td><td>Rápida popularización, fuerte capacidad de avance</td></tr></tbody></table><p>Los distintos tipos pueden aprender unos de otros y optimizar continuamente sus propios modelos educativos.</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El sistema de educación simbiótica es la &quot;incubadora de talentos&quot; y el &quot;transmisor de la civilización&quot; de la Civilización Simbiótica del Ancla. A través del sistema educativo de cuatro niveles, los cuatro principios fundamentales y las completas garantías de profesorado y recursos, la educación simbiótica ofrece a cada vida simbiótica un camino completo de crecimiento desde la iniciación hasta la élite, realizando los objetivos educativos de &quot;Un Camino para Todos, Enseñanza según Aptitudes, Aprendizaje Permanente, Avance Conjunto de las Diez Mil Razas&quot;. La universalización y la calidad de la educación son la garantía fundamental para que la civilización simbiótica pueda evolucionar continuamente y para que las Diez Mil Razas avancen juntas.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>43-教育保障法 (Ley de Garantía Educativa)</li><li>36-社会结构与阶层流动 (Estructura Social y Movilidad de Clases)</li><li>10-三百套本源修炼体系总览 (Panorama General de los Trescientos Sistemas de Cultivo del Origen)</li></ul>',57)])])}const v=e(s,[["render",t]]);export{m as __pageData,v as default};
